                    {
                        ptr = (ptr + (field_size * self.capacity));
                    }
                }
            }
            return result;
    }

pub fn items(self: @This(), comptime field: Field) []FieldType(field) {
            return self.slice().items(field);
    }

pub fn set(self: *@This(), index: usize, elem: T) void {
            var slices = self.slice();
            _ = &slices;
            _ = slices.set(index, elem);
    }

pub fn get(self: @This(), index: usize) T {
            return self.slice().get(index);
    }

pub fn append(self: *@This(), gpa: Allocator, elem: T) !void {
            _ = self.#allocator.set(gpa);
            _ = try self.ensureUnusedCapacity(gpa, 1);
            _ = self.appendAssumeCapacity(elem);
    }

pub fn appendAssumeCapacity(self: *@This(), elem: T) void {
            _ = assert((self.len < self.capacity));
            self.len = (self.len + 1);
            _ = self.set((self.len - 1), elem);
    }

pub fn addOne(self: *@This(), allocator: Allocator) Allocator.Error!usize {
            _ = self.#allocator.set(allocator);
            _ = try self.ensureUnusedCapacity(allocator, 1);
            return self.addOneAssumeCapacity();
    }

pub fn addOneAssumeCapacity(self: *@This()) usize {
            _ = assert((self.len < self.capacity));
            const index = self.len;
            self.len = (self.len + 1);
            return index;
    }

pub fn pop(self: *@This()) ?T {
            if ((self.len == 0)) {
                return null;
            }
            const val = self.get((self.len - 1));
            self.len = (self.len - 1);
            return val;
    }

pub fn insert(self: *@This(), gpa: Allocator, index: usize, elem: T) !void {
            _ = self.#allocator.set(gpa);
            _ = try self.ensureUnusedCapacity(gpa, 1);
            _ = self.insertAssumeCapacity(index, elem);
    }

pub fn insertAssumeCapacity(self: *@This(), index: usize, elem: T) void {
            _ = assert((self.len < self.capacity));
            _ = assert((index <= self.len));
            self.len = (self.len + 1);
            const entry = (switch (@typeInfo(T)) {
.@"struct" => elem,
.@"union" => Elem.fromT(elem),
else => unreachable,
});
            const slices = self.slice();
            inline for (0..fields.len) |field_index| {
                const field_info = fields[@as(usize, @intCast(field_index))];
                var field_slice = slices.items(@as(Field, @enumFromInt(field_index)));
                _ = &field_slice;
                var i: usize = (self.len - 1);
                _ = &i;
                while ((i > index)) : (i = (i - 1)) {
                    field_slice[cp_cast_int(usize, i)] = field_slice[@as(usize, @intCast((i - 1)))];
                }
                field_slice[cp_cast_int(usize, index)] = @field(entry, (if (@typeInfo(@TypeOf(field_info)) == .@"enum" or @typeInfo(@TypeOf(field_info)) == .@"union") @tagName(field_info) else field_info.name));
            }
    }

pub fn appendListAssumeCapacity(self: *@This(), other: Self) void {
            const offset = self.len;
            self.len = (self.len + other.len);
            const other_slice = other.slice();
            const this_slice = self.slice();
            inline for (0..fields.len) |i| {
                const field_info = fields[@as(usize, @intCast(i))];
                if ((@sizeOf(field_info.type) != 0)) {
                    const field = @as(Field, @enumFromInt(i));
                    _ = @memcpy(this_slice.items(field)[offset..], other_slice.items(field));
                }
            }
    }

pub fn swapRemove(self: *@This(), index: usize) void {
            const slices = self.slice();
            inline for (0..fields.len) |i| {
                var field_slice = slices.items(@as(Field, @enumFromInt(i)));
                _ = &field_slice;
                field_slice[cp_cast_int(usize, index)] = field_slice[@as(usize, @intCast((self.len - 1)))];
                field_slice[cp_cast_int(usize, (self.len - 1))] = undefined;
            }
            self.len = (self.len - 1);
    }

pub fn orderedRemove(self: *@This(), index: usize) void {
            const slices = self.slice();
            inline for (0..fields.len) |field_index| {
                var field_slice = slices.items(@as(Field, @enumFromInt(field_index)));
                _ = &field_slice;
                var i = index;
                _ = &i;
                while ((i < (self.len - 1))) : (i = (i + 1)) {
                    field_slice[cp_cast_int(usize, i)] = field_slice[@as(usize, @intCast((i + 1)))];
                }
                field_slice[cp_cast_int(usize, i)] = undefined;
            }
            self.len = (self.len - 1);
    }

pub fn resize(self: *@This(), gpa: Allocator, new_len: usize) !void {
            _ = self.#allocator.set(gpa);
            _ = try self.ensureTotalCapacity(gpa, new_len);
            self.len = new_len;
    }

pub fn shrinkAndFree(self: *@This(), gpa: Allocator, new_len: usize) void {
            _ = self.#allocator.set(gpa);
            if ((new_len == 0)) {
                return self.clearAndFree(gpa);
            }
            _ = assert((new_len <= self.capacity));
            _ = assert((new_len <= self.len));
            const other_bytes = (blk_catch_0: { break :blk_catch_0 ((gpa.alignedAlloc(u8, .fromByteUnits(@alignOf(Elem)), capacityInBytes(new_len))) catch |__ce_0| { _ = &__ce_0; const self_slice = self.slice();
            inline for (0..fields.len) |i| {
                const field_info = fields[@as(usize, @intCast(i))];
                if ((@sizeOf(field_info.type) != 0)) {
                    const field = @as(Field, @enumFromInt(i));
                    const dest_slice = self_slice.items(field)[new_len..];
                    _ = @memset(dest_slice, undefined);
                }
            }
            self.len = new_len;
            return; }); });
            var other = Self{ .bytes = other_bytes.ptr, .capacity = new_len, .len = new_len };
            _ = &other;
            self.len = new_len;
            const self_slice = self.slice();
            const other_slice = other.slice();
            inline for (0..fields.len) |i| {
                const field_info = fields[@as(usize, @intCast(i))];
                if ((@sizeOf(field_info.type) != 0)) {
                    const field = @as(Field, @enumFromInt(i));
                    _ = @memcpy(other_slice.items(field), self_slice.items(field));
                }
            }
            _ = gpa.free(self.allocatedBytes());
            self.* = other;
    }

pub fn clearAndFree(self: *@This(), gpa: Allocator) void {
            _ = self.#allocator.set(gpa);
            _ = gpa.free(self.allocatedBytes());
            self.* = Self{  };
    }

pub fn shrinkRetainingCapacity(self: *@This(), new_len: usize) void {
            self.len = new_len;
    }

pub fn clearRetainingCapacity(self: *@This()) void {
            self.len = 0;
    }

pub fn ensureTotalCapacity(self: *@This(), gpa: Allocator, new_capacity: usize) Allocator.Error!void {
            if ((self.capacity >= new_capacity)) {
                return;
            }
            return self.setCapacity(gpa, growCapacity(self.capacity, new_capacity));
    }

pub fn growCapacity(current: usize, minimum: usize) usize {
            var next_cap = current;
            _ = &next_cap;
            while (true) {
                next_cap = (next_cap +| ((next_cap / 2) + init_capacity));
                if ((next_cap >= minimum)) {
                    return next_cap;
                }
            }
    }

pub fn ensureUnusedCapacity(self: *@This(), gpa: Allocator, additional_count: usize) !void {
            _ = self.#allocator.set(gpa);
            return self.ensureTotalCapacity(gpa, (self.len + additional_count));
    }

pub fn setCapacity(self: *@This(), gpa: Allocator, new_capacity: usize) !void {
            _ = self.#allocator.set(gpa);
            _ = assert((new_capacity >= self.len));
            const new_bytes = try gpa.alignedAlloc(u8, .fromByteUnits(@alignOf(Elem)), capacityInBytes(new_capacity));
            if ((self.len == 0)) {
                _ = gpa.free(self.allocatedBytes());
                self.bytes = new_bytes.ptr;
                self.capacity = new_capacity;
                return;
            }
            var other = Self{ .bytes = new_bytes.ptr, .capacity = new_capacity, .len = self.len };
            _ = &other;
            const self_slice = self.slice();
            const other_slice = other.slice();
            inline for (0..fields.len) |i| {
                const field_info = fields[@as(usize, @intCast(i))];
                if ((@sizeOf(field_info.type) != 0)) {
                    const field = @as(Field, @enumFromInt(i));
                    _ = @memcpy(other_slice.items(field), self_slice.items(field));
                }
            }
            _ = gpa.free(self.allocatedBytes());
            self.* = other;
    }

pub fn clone(self: @This(), gpa: Allocator) !Self {
            var result = Self{  };
            _ = &result;
            errdefer {
            _ = result.deinit(gpa);
            }
            _ = try result.ensureTotalCapacity(gpa, self.len);
            result.len = self.len;
            const self_slice = self.slice();
            const result_slice = result.slice();
            inline for (0..fields.len) |i| {
                const field_info = fields[@as(usize, @intCast(i))];
                if ((@sizeOf(field_info.type) != 0)) {
                    const field = @as(Field, @enumFromInt(i));
                    _ = @memcpy(result_slice.items(field), self_slice.items(field));
                }
            }
            return result;
    }

pub fn sortInternal(self: @This(), a: usize, b: usize, ctx: anytype, comptime mode: std.sort.Mode) void {
            const SortContext = MultiArrayListSortContext(@TypeOf(ctx), Slice, Field, fields);
            const sort_context = SortContext{ .sub_ctx = ctx, .slice = self.slice() };
            switch (mode) {
.stable => {
_ = mem.sortContext(a, b, sort_context);
},
.unstable => {
_ = mem.sortUnstableContext(a, b, sort_context);
},
}
    }

pub fn sort(self: @This(), ctx: anytype) void {
            _ = self.sortInternal(0, self.len, ctx, .stable);
    }

pub fn sortSpan(self: @This(), a: usize, b: usize, ctx: anytype) void {
            _ = self.sortInternal(a, b, ctx, .stable);
    }

pub fn sortUnstable(self: @This(), ctx: anytype) void {
            _ = self.sortInternal(0, self.len, ctx, .unstable);
    }

pub fn sortSpanUnstable(self: @This(), a: usize, b: usize, ctx: anytype) void {
            _ = self.sortInternal(a, b, ctx, .unstable);
    }

pub fn capacityInBytes(capacity: usize) usize {
            return (elem_bytes_sum * capacity);
    }

pub fn allocatedBytes(self: @This()) []align(@alignOf(Elem)) u8 {
            {
                return self.bytes[0..capacityInBytes(self.capacity)];
            }
    }

pub fn memoryCost(self: @This()) usize {
            return capacityInBytes(self.capacity);
    }

pub fn zero(self: @This()) void {
            _ = @memset(self.allocatedBytes(), 0);
    }

pub fn FieldType(comptime field: Field) type {
            return @FieldType(Elem, @tagName(field));
    }

pub fn dbHelper(self: *@This(), child: *Elem, field: *Field, entry: *Entry) void {
            _ = self;
            _ = child;
            _ = field;
            _ = entry;
            if (comptime ((builtin.zig_backend == .stage2_llvm) and (!builtin.strip_debug_info))) {
                _ = Slice.dbHelper;
            }
    }
    const Self = @This();
    pub const empty: Self = initEmpty();
    const Elem = ElemType;
    pub const Field = FieldEnum;
    const fields = elem_fields;
    const sizes = computed_sizes;
    const Entry = EntryType;
    const init_capacity = init_cap;
    pub const Slice = MultiArrayListSlice(T, Self, Elem, Field, Entry, fields, sizes);
};
